APP = "/kaggle/working/planforge"
zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(APP_ZIP.split())))).extractall(APP)
# Kaggle already has torch (GPU): install the engine packages plus the PyTorch extras (timm, smp, ultralytics)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-r", f"{APP}/requirements-torch.txt"], check=False, cwd=APP)

subprocess.run("pkill -f 'uvicorn server:app'; pkill -f cloudflared", shell=True)
srv = subprocess.Popen([sys.executable, "-m", "uvicorn", "server:app", "--host", "0.0.0.0", "--port", "7860"],
                       cwd=APP, stdout=open("/kaggle/working/server.log", "w"), stderr=subprocess.STDOUT)
for _ in range(60):
    try:
        urllib.request.urlopen("http://127.0.0.1:7860/api/catalog", timeout=2); break
    except Exception:
        time.sleep(2)
print("server up")

CF = "/kaggle/working/cloudflared"
if not os.path.exists(CF):
    urllib.request.urlretrieve("https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64", CF)
    os.chmod(CF, 0o755)
tun = subprocess.Popen([CF, "tunnel", "--no-autoupdate", "--url", "http://127.0.0.1:7860"],
                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
url = None
for line in tun.stdout:
    m = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com", line)
    if m:
        url = m.group(0); break
print("\n" + "=" * 70 + "\n  PlanForge is live:  " + str(url) + "\n" + "=" * 70)
print("Use it from the website:  https://<your-site>.vercel.app/?api=" + str(url))
print("server log: /kaggle/working/server.log")
